const MILLISECONDS_PER_DAY = 24 * 60 * 60 * 1000
const relativeTimeFormatter = new Intl.RelativeTimeFormat(undefined, { numeric: "auto" })
const dateTimeFormatters = new Map()

export function signedDifferenceInDays(fromDate, toDate) {
  return localDayNumber(toDate) - localDayNumber(fromDate)
}

export function formatLocalTime(value, format = "smart", now = new Date()) {
  const date = parseLocalDateTime(value)

  if (!date) return value

  switch (format) {
    case "time":
      return formatDate(date, { hour: "numeric", minute: "2-digit" })
    case "date":
      return formatShortDate(date, now)
    case "date-year":
      return formatDate(date, { year: "numeric", month: "short", day: "numeric" })
    case "weekday":
      return formatDate(date, { weekday: "long", month: "long", day: "numeric" })
    case "date-time":
      return formatDate(date, { dateStyle: "medium", timeStyle: "short" })
    case "calendar-relative":
      return relativeTimeFormatter.format(signedDifferenceInDays(now, date), "day")
    case "relative":
      return formatRelativeTime(date, now)
    case "smart":
      return formatSmartTime(date, now)
    default:
      return formatShortDate(date, now)
  }
}

function formatSmartTime(date, now) {
  const days = signedDifferenceInDays(now, date)

  if (days === 0) {
    return formatLocalTime(date, "time", now)
  } else if (days >= -6) {
    return relativeTimeFormatter.format(days, "day")
  } else {
    return formatShortDate(date, now)
  }
}

function formatRelativeTime(date, now) {
  const differenceInSeconds = (date.getTime() - now.getTime()) / 1000
  const absoluteDifference = Math.abs(differenceInSeconds)

  if (absoluteDifference < 60) {
    return differenceInSeconds < 0 ? "just now" : "in a few seconds"
  } else if (absoluteDifference < 60 * 60) {
    return relativeTimeFormatter.format(Math.round(differenceInSeconds / 60), "minute")
  } else if (absoluteDifference < 24 * 60 * 60) {
    return relativeTimeFormatter.format(Math.round(differenceInSeconds / (60 * 60)), "hour")
  } else {
    return relativeTimeFormatter.format(Math.round(differenceInSeconds / (24 * 60 * 60)), "day")
  }
}

function formatShortDate(date, now) {
  const options = { month: "short", day: "numeric" }

  if (date.getFullYear() !== now.getFullYear()) {
    options.year = "numeric"
  }

  return formatDate(date, options)
}

function formatDate(date, options) {
  const key = JSON.stringify(options)
  let formatter = dateTimeFormatters.get(key)

  if (!formatter) {
    formatter = new Intl.DateTimeFormat(undefined, options)
    dateTimeFormatters.set(key, formatter)
  }

  return formatter.format(date)
}

function parseLocalDateTime(value) {
  if (value instanceof Date) {
    return Number.isNaN(value.getTime()) ? null : value
  }

  const dateOnly = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value)

  if (dateOnly) {
    const [, year, month, day] = dateOnly.map(Number)
    return new Date(year, month - 1, day)
  }

  const date = new Date(value)
  return Number.isNaN(date.getTime()) ? null : date
}

function localDayNumber(date) {
  return Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()) / MILLISECONDS_PER_DAY
}
